const job = $input.first().json;
const ctx = $('Identificar job').first().json;
const config = $('Entrada de teste').first().json;
const attempt = $runIndex + 1;
const completed = job.type === 'CompletedJob' || job.completed_at != null || typeof job.success === 'boolean';
if (job.canceled || job.is_canceled || (completed && job.success !== true)) throw new Error('Renderização falhou ou foi cancelada. Job: '+ctx.windmill_job_url);
if (!completed && attempt >= config.poll.max_attempts) throw new Error('Tempo de acompanhamento esgotado; o job pode continuar no Windmill. Não reenvie a renderização automaticamente. Job: '+ctx.windmill_job_url);
return [{json:{...ctx,completed,attempt,result:completed ? job.result : null}}];

const item=$input.first().json;
