if(!result?.output||!result.media) throw new Error('Resultado incompleto. Job: '+item.windmill_job_url);
const editorial=$('Montar contrato da IA').first().json;
return [{json:{status:'completed',windmill_job_url:item.windmill_job_url,...result,editorial:{brief:editorial.brief,content_plan:editorial.content_plan,review:editorial.editorial_review,actual_seconds:result.media.duration_seconds,audio_enhancement:editorial.payload.edit.audio?.enhancement??'off'}}}];

const raw = $input.first().json;
const evidence = $('Preparar evidencias').first().json;
const duration = evidence.media?.duration_seconds;
if (!Number.isFinite(duration) || !Array.isArray(evidence.frames) || evidence.frames.length !== 6) throw new Error('Evidências ausentes ou incompletas.');
if (!raw || raw.error || !Array.isArray(raw.segments) || !Array.isArray(raw.words)) throw new Error('ASR não retornou segmentos e palavras com timestamps. Não estimar tempos por IA.');
const finiteRange = x => Number.isFinite(x.start) && Number.isFinite(x.end) && x.start >= 0 && x.end > x.start && x.end <= duration + 0.15;
const rawWords = raw.words.map(w => ({start:w.start,end:w.end,text:String(w.word ?? w.text ?? '').trim()})).filter(w => w.text);
if (rawWords.some(w => !Number.isFinite(w.start) || !Number.isFinite(w.end) || w.start<0 || w.end<w.start || w.end>duration+1 || w.start>duration+1)) throw new Error('Timestamps de palavras inválidos.');
const paddingAdjusted=rawWords.some(w=>w.end>duration)||raw.segments.some(s=>s.end>duration);
const words = rawWords.map(w=>({...w,start:Math.min(w.start,duration),end:Math.min(w.end,duration)})).filter(w=>w.end>w.start);
const overlappingWords=words.some((w,i)=>i>0 && w.start<words[i-1].end-0.000001);
const segments = raw.segments.map((s,id)=>({id,start:s.start,end:Math.min(s.end,duration),text:String(s.text ?? '').trim(),no_speech_prob:s.no_speech_prob ?? null})).filter(s=>s.text);
if (!segments.length || segments.some(s=>!finiteRange(s))) throw new Error('Segmentos de transcrição inválidos.');
return [{json:{media:evidence.media,transcript:{text:String(raw.text||segments.map(s=>s.text).join(' ')),segments,words,timing_basis:'asr_segments',warnings:[...(overlappingWords ? ['ASR trouxe palavras sobrepostas; esta integração usa legendas por segmento, sem destaque por palavra.'] : []),...(rawWords.length!==words.length ? ['ASR retornou palavras sem duração; cortes e legendas usam segmentos reais, sem estimar tempos.'] : []),...(paddingAdjusted ? ['Timestamps finais do ASR limitados à duração real da mídia (padding de até 1 s).'] : [])]},usage:raw.usage ?? null}}];

const raw=$input.first().json;
let plan=raw.output ?? raw.text ?? raw;
if(typeof plan==='string') plan=JSON.parse(plan.replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,''));
const source=$('Normalizar transcricao').first().json;
const config=$('Entrada de teste').first().json;
const brief=$('Normalizar briefing').first().json.brief;
if(!plan||plan.schema_version!=='1.1'||!['ready','message_not_found','review_required'].includes(plan.status)||typeof plan.main_message!=='string'||typeof plan.summary!=='string'||!Array.isArray(plan.clips)||plan.clips.length>6||!Array.isArray(plan.warnings)||plan.warnings.some(w=>typeof w!=='string')) throw new Error('Plano editorial inválido.');
if(Object.keys(plan).some(k=>!['schema_version','status','main_message','summary','clips','quality','warnings'].includes(k))) throw new Error('Campo editorial desconhecido.');
const q=plan.quality;
if(!q||typeof q.opening_complete!=='boolean'||typeof q.ending_complete!=='boolean'||typeof q.message_supported!=='boolean'||typeof q.reason!=='string') throw new Error('Revisão editorial ausente.');
if(plan.status!=='ready'){
  if(plan.clips.length) throw new Error('Plano não aprovado não pode conter recortes executáveis.');
  return [{json:{content_plan:plan,duration_seconds:0,brief}}];
}
if(!plan.clips.length||!plan.main_message.trim()||!q.opening_complete||!q.ending_complete||!q.message_supported) throw new Error('Conteúdo marcado pronto sem mensagem ou fechamento completos.');
const segments=new Map(source.transcript.segments.map(s=>[s.id,s]));
const clips=plan.clips.map(c=>{
  if(Object.keys(c).some(k=>!['start_segment_id','end_segment_id','reason','pre_roll_seconds','post_roll_seconds'].includes(k))||!Number.isInteger(c.start_segment_id)||!Number.isInteger(c.end_segment_id)||c.end_segment_id<c.start_segment_id||typeof c.reason!=='string') throw new Error('Referência de segmento inválida.');
  for(const k of ['pre_roll_seconds','post_roll_seconds']) if(c[k]!=null && (!Number.isFinite(c[k])||c[k]<0||c[k]>1.5)) throw new Error('Margem de corte inválida.');
  const first=segments.get(c.start_segment_id),last=segments.get(c.end_segment_id);
  if(!first||!last) throw new Error('Segmento inexistente.');
  const before=source.transcript.segments.find(s=>s.id===first.id-1);
  const after=source.transcript.segments.find(s=>s.id===last.id+1);
  const start=Math.max(0,first.start-Math.min(c.pre_roll_seconds??0,Math.max(0,first.start-(before?.end??0))));
  const end=Math.min(source.media.duration_seconds,last.end+Math.min(c.post_roll_seconds??0,Math.max(0,(after?.start??source.media.duration_seconds)-last.end)));
  if(end<=start||end>source.media.duration_seconds) throw new Error('Intervalo inválido.');
  return {source_in:start,source_out:end,reason:c.reason};
});
for(let i=0;i<clips.length;i++)for(let j=i+1;j<clips.length;j++)if(Math.max(clips[i].source_in,clips[j].source_in)<Math.min(clips[i].source_out,clips[j].source_out))throw new Error('Cortes sobrepostos ou repetidos.');
const duration=clips.reduce((n,c)=>n+c.source_out-c.source_in,0);
if(duration>config.policy.max_output_seconds+0.001) throw new Error('Mensagem excede o limite técnico. Replanejar; nunca truncar automaticamente.');
const editorial_context=plan.clips.map(c=>({
  selected_segments:source.transcript.segments.filter(s=>s.id>=c.start_segment_id&&s.id<=c.end_segment_id),
  preceding_segments:source.transcript.segments.filter(s=>s.id>=c.start_segment_id-2&&s.id<c.start_segment_id),
  following_segments:source.transcript.segments.filter(s=>s.id>c.end_segment_id&&s.id<=c.end_segment_id+3)
}));
return [{json:{content_plan:{...plan,clips},duration_seconds:duration,brief,editorial_context,duration_vs_suggestion_seconds:duration-brief.target_duration_seconds}}];

const raw = $input.first().json;
let response = raw.output ?? raw.text ?? raw;
if(typeof response==='string') response=JSON.parse(response.replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,''));
if(!response||Object.keys(response).some(k=>!['review','edit','content_plan','attempt','revision_feedback','generated_asset','music_prompt','needs_music'].includes(k))) throw new Error('Resposta de arte inválida.');
const review=response.review;
if(!review||typeof review.reason!=='string'||!['accepted','opening_complete','ending_complete','message_supported','matches_requested_message'].every(k=>review[k]===true)) throw new Error('EDITORIAL_REVIEW_REQUIRED: '+(review?.reason??'Revisão de coerência ausente.'));
let edit=response.edit;
const config = $('Entrada de teste').first().json;
const content = response.content_plan ?? $('Validar plano de conteudo').first().json.content_plan;
const transcript = $('Normalizar transcricao').first().json.transcript;
if(!edit || edit.source_mode!=='working' || !Array.isArray(edit.clips) || edit.clips.length!==content.clips.length) throw new Error('Diretor de arte alterou o modo de fonte ou os recortes.');
edit.clips.forEach((c,i)=>{const a=content.clips[i];if(Math.abs(c.source_in-a.source_in)>0.001 || Math.abs(c.source_out-a.source_out)>0.001 || (c.speed??1)!==1) throw new Error('Diretor de arte alterou um corte aprovado.');c.source_in=a.source_in;c.source_out=a.source_out;});
if('captions' in edit) throw new Error('Legendas devem vir do ASR, não de tempos inventados pelo diretor de arte.');
const catalog = new Map(config.payload.edit.assets.map(a=>[a.id,a]));
const music=$('Normalizar briefing').first().json.brief.music;
if(response.generated_asset) catalog.set('generated_music',response.generated_asset);
if(music.mode==='none' && (edit.audio_tracks??[]).length) throw new Error('Trilha não solicitada.');
for(const t of edit.audio_tracks??[]) if(t.asset_id!==(music.mode==='generate'?'generated_music':music.asset_id)) throw new Error('Trilha não autorizada.');
for(const a of edit.assets??[]){const expected=catalog.get(a.id);if(!expected || a.type!==expected.type || JSON.stringify(a.source)!==JSON.stringify(expected.source)) throw new Error('Asset inventado ou fonte alterada pela IA.');}
// Segmentos reais completos; o editor remapeia cortes e ordem. Sem inventar tempos de palavras.
const segments=[];
for(const clip of edit.clips){
  for(const s of transcript.segments.filter(s=>s.start>=clip.source_in && s.end<=clip.source_out)) {
    if(s.text.length>200) throw new Error('Segmento ASR excede o limite de 200 caracteres.');
    segments.push({start:s.start,end:s.end,text:s.text});
  }
}
segments.sort((a,b)=>a.start-b.start);
if(!segments.length) throw new Error('Nenhuma legenda real nos recortes escolhidos.');
edit.captions={timing_basis:'source',style:'clean',burn_in:true,export_formats:['srt','ass'],segments};
return [{json:{editorial_review:review,brief:$('Normalizar briefing').first().json.brief,payload:{working_source:config.payload.working_source,edit},policy:config.policy,poll:config.poll,content_plan:content,ai_models:config.ai}}];

const config=$input.first().json;
const input=config.user_input ?? {};
if(!input || typeof input!=='object' || Array.isArray(input)) throw new Error('user_input deve ser um objeto.');
if(Object.keys(input).some(k=>!['main_message','target_duration_seconds','music'].includes(k))) throw new Error('Campo desconhecido no briefing do usuário.');
if(input.main_message!=null && typeof input.main_message!=='string') throw new Error('main_message deve ser texto ou null.');
const main_message=input.main_message?.trim() || null;
if(main_message && main_message.length>1000) throw new Error('main_message excede 1000 caracteres.');
const target=input.target_duration_seconds ?? config.brief?.target_duration_seconds ?? config.brief?.target_seconds ?? 45;
if(!Number.isFinite(target) || target<=0 || target>3600) throw new Error('Duração sugerida inválida.');
const music=input.music ?? {mode:'none'};
if(!music||typeof music!=='object'||Array.isArray(music)||!['none','asset','generate'].includes(music.mode)||Object.keys(music).some(k=>!['mode','asset_id','prompt'].includes(k))) throw new Error('Configuração de trilha inválida.');
if(music.prompt!=null && (typeof music.prompt!=='string'||music.prompt.length>1000)) throw new Error('Prompt de trilha inválido.');
if(music.mode==='asset' && !config.payload.edit.assets.some(a=>a.id===music.asset_id&&a.type==='audio')) throw new Error('Trilha enviada não existe no catálogo autorizado.');
const {target_seconds,...base}=config.brief ?? {};
return [{json:{brief:{...base,music,mode:main_message?'user_guided':'automatic',main_message,target_duration_seconds:target,duration_is_suggestion:true,hard_max_seconds:config.policy.max_output_seconds}}}];

const input=$input.first().json;
let response=input.output??input.text??input;
if(typeof response==='string') response=JSON.parse(response.replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,''));
const plan=$('Validar plano de conteudo').first(0,$runIndex).json.content_plan;
const review=response.review;
if(!review||typeof review.reason!=='string'||!Array.isArray(review.clip_reviews)||review.clip_reviews.length!==plan.clips.length) throw new Error('Revisão individual dos recortes ausente.');
const contexts=$('Validar plano de conteudo').first(0,$runIndex).json.editorial_context;
const normalize=t=>t.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'');
const clipApproved=review.clip_reviews.every((r,i)=>r.clip_index===i && r.opening_complete===true && r.ending_complete===true && typeof r.reason==='string' && typeof r.closing_text==='string' && normalize(contexts[i].selected_segments.map(s=>s.text).join(' ')).endsWith(normalize(r.closing_text)) && normalize(r.closing_text).length>0);
const lastContext=contexts[contexts.length-1];
const lastSpeechEnd=Math.max(...lastContext.selected_segments.map(s=>s.end));
const availableTail=Math.max(0,plan.clips[plan.clips.length-1].source_out-lastSpeechEnd);
const ending=response.edit?.ending??{};
const fade=Math.max(ending.audio_fade_out_seconds??0,ending.video_fade_out_seconds??0);
const fadeSafe=Number.isFinite(fade)&&fade<=availableTail+0.001;
const hanging=review.clip_reviews.some(r=>typeof r.closing_text==='string'&&/(?:^|\s)(e|ou|mas|porque|então|por exemplo)[\s,.!?…]*$/iu.test(r.closing_text));
const technicalReason=!fadeSafe?'Fade invade a última fala: margem disponível '+availableTail.toFixed(3)+'s, fade solicitado '+fade+'s. Selecione fechamento com pausa suficiente e escolha fade dentro da margem.':hanging?'Recorte termina em conectivo pendente. Inclua a conclusão real ou escolha outro fechamento.':'';
const accepted=fadeSafe&&!hanging&&['accepted','opening_complete','ending_complete','message_supported','matches_requested_message'].every(k=>review[k]===true)&&clipApproved;
return [{json:{content_plan:plan,review:{...review,accepted},edit:response.edit,music_prompt:response.music_prompt??null,attempt:$runIndex+1,revision_feedback:{reason:technicalReason||review.reason,clip_reviews:review.clip_reviews}}}];

const item=$input.first().json;
if(item.attempt>=2) throw new Error('EDITORIAL_REVIEW_REQUIRED: duas seleções reprovadas; não renderizar. '+item.review.reason);
return [{json:{...$('Normalizar transcricao').first().json,revision_feedback:item.revision_feedback}}];

const response=$input.first().json;
const mode=$('Normalizar briefing').first().json.brief.music.mode;
const needs_music=mode==='generate';
if(needs_music && (typeof response.music_prompt!=='string'||!response.music_prompt.trim()||response.music_prompt.length>2000)) throw new Error('Direção musical ausente.');
if(needs_music && !response.edit?.audio_tracks?.some(t=>t.asset_id==='generated_music')) throw new Error('Plano não utiliza a trilha solicitada.');
return [{json:{...response,needs_music}}];

const raw=$input.first().json.data;
if(typeof raw!=='string'||raw.length>30*1024*1024) throw new Error('Resposta musical ausente ou grande demais.');
const chunks=[]; let done=false;
for(const line of raw.split(/\r?\n/)){
 if(!line.startsWith('data:')) continue;
 const text=line.slice(5).trim(); if(text==='[DONE]'){done=true;continue;} if(!text)continue;
 const event=JSON.parse(text); if(event.error)throw new Error('Falha no provedor musical.');
 const data=event.choices?.[0]?.delta?.audio?.data;
 if(data){if(typeof data!=='string'||!/^[A-Za-z0-9+/]*={0,2}$/.test(data))throw new Error('Chunk musical inválido.');chunks.push(Buffer.from(data,'base64'));}
}
if(!done||!chunks.length)throw new Error('Geração musical incompleta ou sem áudio.');
const audio=Buffer.concat(chunks);if(audio.length>20*1024*1024)throw new Error('Trilha excede o limite.');
return [{json:{data:audio.toString('base64')}}];

const result=$input.first().json;
const response=$('Preparar trilha').first().json;
if(result.asset?.id!=='generated_music'||result.asset?.type!=='audio'||!result.asset.source?.key) throw new Error('Asset musical não armazenado.');
response.edit.assets=(response.edit.assets??[]).map(a=>a.id==='generated_music'?result.asset:a);
return [{json:{...response,generated_asset:result.asset}}];
